From 7d2ae03d6450abfdf5699ceac70d09fc4eb88aaf Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:45:18 +0100
Subject: [PATCH] containments/desktop: Keep handle tooltips off the buttons of
 rotated widgets

On a rotated widget, only the tooltip's position was mapped through the
rotation, so it could land right on its button, swallow every press and
make the rotate button unusable. Place it above the button's bounds.

BUG: 523678
---
 .../desktop/package/contents/ui/ActionButton.qml    | 13 +++++++++++++
 1 file changed, 13 insertions(+)

diff --git a/containments/desktop/package/contents/ui/ActionButton.qml b/containments/desktop/package/contents/ui/ActionButton.qml
index 2ea968de1c..8e0572f995 100644
--- a/containments/desktop/package/contents/ui/ActionButton.qml
+++ b/containments/desktop/package/contents/ui/ActionButton.qml
@@ -41,5 +41,18 @@ PC3.ToolButton {
         visible: button.hovered && text.length > 0
         Kirigami.Theme.colorSet: Kirigami.Theme.Window
         Kirigami.Theme.inherit: false
+
+        // Popups are not rotated with their parent, only their position is mapped through
+        // the rotation, so place the tooltip above the button's on-screen bounds instead
+        onAboutToShow: {
+            const corners = [button.mapToItem(null, 0, 0), button.mapToItem(null, button.width, 0),
+                             button.mapToItem(null, 0, button.height), button.mapToItem(null, button.width, button.height)];
+            const left = Math.min(...corners.map(p => p.x));
+            const right = Math.max(...corners.map(p => p.x));
+            const top = Math.min(...corners.map(p => p.y));
+            const pos = button.mapFromItem(null, Math.round((left + right - implicitWidth) / 2), Math.round(top - implicitHeight - 3));
+            x = pos.x;
+            y = pos.y;
+        }
     }
 }
